// Eingabe pruefen, bevor irgendetwas passiert. Wortgleich zu
// sub-duo-versand; beide Subs haben denselben Vertrag, also auch
// dieselbe Eingangspruefung.
const a = $('Aufruf').first().json ?? {};

const ids = (Array.isArray(a.doc_ids) ? a.doc_ids : [a.doc_ids])
  .filter(v => v !== null && v !== undefined && String(v).trim() !== '')
  .map(Number);

if (!ids.length) throw new Error('sub-stb-versand ohne Belege aufgerufen: doc_ids ist leer. Der Aufrufer haette gar nicht rufen duerfen.');
if (ids.some(n => !Number.isFinite(n))) throw new Error('doc_ids enthaelt etwas, das keine Zahl ist: ' + JSON.stringify(a.doc_ids));
if (String(a.empfaenger ?? '').indexOf('@') === -1) throw new Error('Keine Kanzlei-Adresse uebergeben. In der n8n-Oberflaeche unter "Data Tables" den Schluessel mail_stb setzen.');
if (String(a.absender ?? '').indexOf('@') === -1) throw new Error('Keine Absenderadresse uebergeben: pw_config, Schluessel mail_absender.');
if (!Number.isFinite(Number(a.tag_gesendet_id))) throw new Error('tag_gesendet_id fehlt; der Aufrufer muss die Paperless-ID von "Steuer-gesendet" mitgeben.');

return [{ json: {
  doc_ids: ids,
  id_liste: ids.join(','),
  paperless_url: String(a.paperless_url).replace(/\/+$/, ''),
  empfaenger: a.empfaenger,
  absender: a.absender,
  dateiname_quelle: a.dateiname_quelle || 'titel',
  // Der Zeitraum landet im Zip- und CSV-Dateinamen, muss also
  // dateisystemtauglich sein. Faellt er aus, gilt das Datum.
  zeitraum: String(a.zeitraum || new Date().toISOString().slice(0, 10)).replace(/[\\/:*?"<>|\s]+/g, '-'),
  tag_gesendet_id: Number(a.tag_gesendet_id)
} }];

// Pro Beleg vorbereiten: Download-URL (Original bei PDF/TIF/TIFF,
// sonst Archiv-PDF), einen im Zip eindeutigen Dateinamen mit
// laufender Nummer, und den Korrespondentennamen fuer die CSV.
const auftrag = $('Auftrag prüfen').first().json;
const docs = $('Dokumente laden').first().json.results || [];
const okExt = ['.pdf', '.tif', '.tiff'];

// Stille Datenverluste sichtbar machen, siehe sub-duo-versand.
if (docs.length !== auftrag.doc_ids.length) {
  const da = docs.map(d => d.id);
  const fehlt = auftrag.doc_ids.filter(id => !da.includes(id));
  throw new Error('Paperless lieferte ' + docs.length + ' von ' + auftrag.doc_ids.length + ' angeforderten Belegen. Fehlend: ' + fehlt.join(', ') + '. Entweder wurden sie zwischenzeitlich geloescht, oder es waren mehr als 250 auf einmal.');
}

const korr = {};
($input.first().json.results || []).forEach(k => { korr[k.id] = k.name; });

return docs.map((d, i) => {
  const orig = d.original_file_name || '';
  const name = orig.toLowerCase();
  const useOriginal = okExt.some(ext => name.endsWith(ext));

  const dotPos = orig.lastIndexOf('.');
  const ext = (useOriginal && dotPos > 0) ? orig.slice(dotPos).toLowerCase() : '.pdf';
  let base;
  if (auftrag.dateiname_quelle === 'original' && orig) {
    base = dotPos > 0 ? orig.slice(0, dotPos) : orig;
  } else {
    base = d.title || ('Beleg-' + d.id);
  }
  base = base.replace(/[\\/:*?"<>|\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
  if (!base) base = 'Beleg-' + d.id;

  return { json: {
    nr: i + 1,
    id: d.id,
    title: d.title || ('Dokument ' + d.id),
    created: d.created,
    korrespondent: d.correspondent ? (korr[d.correspondent] || '') : '',
    original_file_name: orig || null,
    // Laufende Nummer als Praefix: zwei Belege duerfen denselben Titel
    // tragen, im Zip waere der zweite sonst weg.
    zip_name: String(i + 1).padStart(3, '0') + '_' + base + ext,
    download_url: auftrag.paperless_url + '/api/documents/' + d.id + '/download/' + (useOriginal ? '?original=true' : '')
  }};
});

// Dateiname aus der Dokumentliste auf den Download uebernehmen -
// sonst hiesse jede Datei im Zip 'data.pdf'.
const doc = $('Dokumentliste aufbauen').item.json;
const item = $input.item;

if (!item.binary || !item.binary.data) {
  throw new Error('Kein Binaerinhalt fuer Dokument ' + doc.id + ': Download fehlgeschlagen?');
}

item.binary.data.fileName = doc.zip_name;
return item;

// Alle Downloads in EIN Item buendeln, damit der Compression-Knoten
// daraus ein einzelnes Zip baut.
const items = $input.all();
if (!items.length) throw new Error('Keine Belege zum Packen vorhanden.');

const binary = {};
items.forEach((item, i) => {
  if (!item.binary || !item.binary.data) {
    throw new Error('Beleg ohne Binaerdaten an Position ' + (i + 1) + ': Download fehlgeschlagen?');
  }
  binary['file_' + String(i).padStart(3, '0')] = item.binary.data;
});

return [{ json: { anzahl: items.length }, binary }];

// CSV-Belegliste erzeugen und als zweiten Anhang an das Item haengen.
// Semikolon-getrennt und mit BOM, damit deutsches Excel sie direkt
// sauber oeffnet; mit Komma und ohne BOM landet alles in Spalte A.
const auftrag = $('Auftrag prüfen').first().json;
const docs = $('Dokumentliste aufbauen').all().map(i => i.json);

const esc = (v) => '"' + String(v ?? '').replace(/"/g, '""') + '"';
const header = ['Nr', 'Paperless-ID', 'Titel', 'Belegdatum', 'Korrespondent', 'Original-Dateiname', 'Datei im ZIP'].join(';');
const lines = docs.map(d => [
  d.nr,
  d.id,
  esc(d.title),
  d.created ? String(d.created).slice(0, 10) : '',
  esc(d.korrespondent),
  esc(d.original_file_name || ''),
  esc(d.zip_name)
].join(';'));
const csv = '\ufeff' + header + '\n' + lines.join('\n') + '\n';

const item = $input.first();
item.binary = item.binary || {};
item.binary.csv = await this.helpers.prepareBinaryData(
  Buffer.from(csv, 'utf8'),
  'Belegliste-' + auftrag.zeitraum + '.csv',
  'text/csv'
);
item.json.anzahl = docs.length;
return item;

// Ergebnis an den Aufrufer, mit derselben Struktur wie sub-duo-versand,
// damit der Monatslauf seinen Bericht bauen kann, ohne zu wissen,
// welcher Kanal gelaufen ist.
const docs = $('Dokumentliste aufbauen').all().map(i => i.json);
const auftrag = $('Auftrag prüfen').first().json;
return [{ json: {
  status: 'gesendet',
  kanal: 'StB',
  anzahl: docs.length,
  doc_ids: docs.map(d => d.id),
  belege: docs.map(d => ({ id: d.id, titel: d.title, created: d.created, datei: d.zip_name })),
  zeitraum: auftrag.zeitraum
} }];
